"""Regression against synthetic outputs generated by the original author code.

Reference source: scaomath/galerkin-transformer revision
f9e7d6abc24e958b1165f48b22625c5bab688043. The fixture contains random synthetic
weights and data only. Original functional attention dropout was disabled in
eval, as in the deterministic frozen-teacher policy. No normalization or boundary
mask is applied. See data/generate_galerkin_reference.py for reproducibility.
"""

from pathlib import Path

import pytest
import torch

from neuralop.models import GalerkinTransformer


@pytest.mark.parametrize(
    "case_index", [0, 1], ids=["without_layer_norm", "with_layer_norm"]
)
def test_matches_original_author_reference(case_index):
    fixture = torch.load(
        Path(__file__).with_name("data") / "galerkin_reference.pt",
        map_location="cpu",
        weights_only=True,
    )
    assert fixture["source_revision"] == "f9e7d6abc24e958b1165f48b22625c5bab688043"
    case = fixture["cases"][case_index]
    model = GalerkinTransformer(**case["model_kwargs"]).eval()
    model.load_author_state_dict(case["state_dict"])
    x = case["x"].clone().requires_grad_(True)
    result = model(x, pos=case["pos"], grid=case["grid"])
    gradient = torch.autograd.grad(result.square().sum(), x)[0]
    torch.testing.assert_close(result, case["output"], rtol=1e-6, atol=1e-6)
    torch.testing.assert_close(gradient, case["input_gradient"], rtol=1e-6, atol=1e-6)
    with torch.no_grad():
        generated_coordinates = model(x.detach())
    torch.testing.assert_close(
        generated_coordinates, case["output"], rtol=1e-6, atol=1e-6
    )
